"""Render batch 6 (p33-p36) content-only Instagram carousels for the 4 new guide articles; captions kept alongside slides."""
import json, os, subprocess

def slide(image, tag, title, sub, last=False):
    return {"bg": image,
            "body": f'<span class="tag">{tag}</span><h1>{title}</h1><p class="sub">{sub}</p>',
            "swipe": "FullBody.co.il" if last else "ממשיכים שמאלה ←"}

END = "המדריך המלא באתר – לינק בביו"
BLOG = "public/images/blog"
